python - <<'PY'
import csv,numpy as np
from pymatgen.core import Structure
rs={r['candidate_id']:r for r in csv.DictReader(open('nlo_pool.csv'))}
for cid in ['c038','c074','c079','c080','c061','c089','c007','c049','c069','c076','c077','c078','c092']:
 s=Structure.from_str(rs[cid]['poscar'],fmt='poscar')
 print('\n',cid,rs[cid]['formula'])
 # bonds cutoff based each atom 2.9, list species directional unit tensor eigenvalues aggregate among unlike bonds
 E=[]
 for i,x in enumerate(s):
  for n in s.get_neighbors(x,3.1):
   if n.index>i and x.specie.symbol!=n.specie.symbol:
    v=n.coords-x.coords; d=np.linalg.norm(v)
    # plausible covalent/ionic limit
    if d<3.1: E.append(v/d)
 E=np.array(E)
 T=(E[:,:,None]*E[:,None,:]).mean(0)
 print('n',len(E),'eig',np.linalg.eigvalsh(T).round(3),'vectors\n',np.linalg.eigh(T)[1].round(2))
