import csv,numpy as np
from pymatgen.core import Structure
rs={r['candidate_id']:r for r in csv.DictReader(open('nlo_pool.csv'))}
for cid in ['c038','c074','c083']:
 s=Structure.from_str(rs[cid]['poscar'],fmt='poscar');print(cid)
 for i,x in enumerate(s):
  if x.specie.symbol in ['Sb','As']:
   vs=np.array([n.coords-x.coords for n in s.get_neighbors(x,3.0) if n.specie.symbol in ['S','Se']])
   print(x.specie.symbol,np.round(vs.sum(0)/np.linalg.norm(vs.sum(0)),3))
